const BASE:u64=0x400000;
fn p16(b:&mut[u8],o:usize,n:u16){b[o..o+2].copy_from_slice(&n.to_le_bytes())}fn p32(b:&mut[u8],o:usize,n:u32){b[o..o+4].copy_from_slice(&n.to_le_bytes())}fn p64(b:&mut[u8],o:usize,n:u64){b[o..o+8].copy_from_slice(&n.to_le_bytes())}
pub fn executable(machine_code:&[u8])->Vec<u8>{let off=120usize;let size=off+machine_code.len();let mut b=vec![0u8;size];b[..4].copy_from_slice(b"\x7fELF");b[4]=2;b[5]=1;b[6]=1;p16(&mut b,16,2);p16(&mut b,18,62);p32(&mut b,20,1);p64(&mut b,24,BASE+off as u64);p64(&mut b,32,64);p16(&mut b,52,64);p16(&mut b,54,56);p16(&mut b,56,1);p32(&mut b,64,1);p32(&mut b,68,5);p64(&mut b,72,0);p64(&mut b,80,BASE);p64(&mut b,88,BASE);p64(&mut b,96,size as u64);p64(&mut b,104,size as u64);p64(&mut b,112,0x1000);b[off..].copy_from_slice(machine_code);b}
#[cfg(test)]mod tests{use super::*;#[test]fn writes_elf64_header(){let b=executable(&[0xc3]);assert_eq!(&b[..4],b"\x7fELF");assert_eq!(b[4],2);assert_eq!(u16::from_le_bytes([b[18],b[19]]),62)}}
